package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;
@Entity @Table(name="supplier_credit_application") public class AplicacionNotaCreditoProveedor{
 @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false)private UUID empresaId;@Column(name="supplier_credit_note_id",nullable=false)private UUID notaId;@Column(name="purchase_invoice_id",nullable=false)private UUID facturaId;@Column(name="accounts_payable_id",nullable=false)private UUID cuentaPagarId;@Column(nullable=false,precision=19,scale=4)private BigDecimal amount;@Column(name="applied_at",nullable=false,insertable=false,updatable=false)private OffsetDateTime aplicadaEn;@Column(name="applied_by",nullable=false)private UUID aplicadaPor;@Column(nullable=false)private boolean reversed;@Column(name="reversed_at")private OffsetDateTime revertidaEn;@Column(name="reversed_by")private UUID revertidaPor;@Column(name="reversal_reason",length=500)private String motivoReversion;
 protected AplicacionNotaCreditoProveedor(){}public AplicacionNotaCreditoProveedor(UUID t,UUID e,UUID n,UUID f,UUID c,BigDecimal monto,UUID u){tenantId=t;empresaId=e;notaId=n;facturaId=f;cuentaPagarId=c;amount=monto;aplicadaPor=u;}public void revertir(String motivo,UUID usuario){reversed=true;motivoReversion=motivo;revertidaPor=usuario;revertidaEn=OffsetDateTime.now();}public UUID getId(){return id;}public UUID getNotaId(){return notaId;}public UUID getFacturaId(){return facturaId;}public UUID getCuentaPagarId(){return cuentaPagarId;}public BigDecimal getMonto(){return amount;}public OffsetDateTime getAplicadaEn(){return aplicadaEn;}public boolean isRevertida(){return reversed;}}
